14	     * toEpoch 早于 fromEpoch 时按同一公式反推（活度增大）。
15	     *
16	     * @param activityAtFrom   fromEpoch 时刻活度，单位 Bq
17	     * @param fromEpoch        标定时刻，UTC epoch 秒
18	     * @param toEpoch          目标时刻，UTC epoch 秒
19	     * @param halfLifeSeconds  半衰期，单位秒，必须为正
20	     * @return toEpoch 时刻活度，单位 Bq
21	     */
22	    public double activityAt(double activityAtFrom, long fromEpoch, long toEpoch, long halfLifeSeconds) {
23	        if (halfLifeSeconds <= 0) {
24	            throw new IllegalArgumentException("halfLifeSeconds must be positive");
25	        }
26	        double elapsedHalves = (double) (toEpoch - fromEpoch) / (double) halfLifeSeconds;
27	        return activityAtFrom * Math.pow(0.5, elapsedHalves);
28	    }
29	
30	    /**
31	     * 衰变残量：初始活度在 [fromEpoch, toEpoch] 区间内因衰变损失的部分，单位 Bq。
32	     */
33	    public double decayResidual(double initialActivity, long fromEpoch, long toEpoch, long halfLifeSeconds) {
34	        return initialActivity - activityAt(initialActivity, fromEpoch, toEpoch, halfLifeSeconds);
